"""Explicit RDD foundations and evidence-driven tuning. --check is read-only."""
from pathlib import Path
import json
import sys
ROOT=Path(__file__).resolve().parents[1]/'src/content'
GUIDES=json.loads((ROOT/'standardGuides.json').read_text(encoding='utf-8'))
DELAYED=json.loads((ROOT/'delayedChecks.json').read_text(encoding='utf-8'))
DELAYED['items']=[i for i in DELAYED['items'] if not i['slug'].startswith(('l1-','l7-'))]
course=json.loads((ROOT.parents[2]/'backend/app/course_seed.json').read_text(encoding='utf-8'))
originals={l['slug']:l['content']['explanation'] for level in course['levels'] for l in level['lessons']}
BASE='https://spark.apache.org/docs/3.5.7/'
lessons={}
def lesson(slug,title,mission,correction,source):
    global current
    current=dict(slug=slug,version=1,title=title,mission=mission,correction=correction,source=BASE+source,
                 next='先用新输入验证你的判断，再继续下一课。正式成绩与本机练习记录分开。',tasks=[])
    lessons[slug]=current
    GUIDES['lessons'][slug]=dict(title=title,sections=[],sources=[dict(title='Spark 3.5.7 官方说明',url=BASE+source)])
def reading(ident,title,body,boundary):
    markers=[line.strip() for line in originals[current['slug']].splitlines() if line.startswith('【')]
    return dict(id=ident+'/reading',title=title,sectionTitle=markers[0].strip('【】'),startMarker=markers[0],endMarker=markers[1],connection=body,boundary=boundary,
                caution='此处保留旧讲义。惰性执行、容错、缓存、默认参数与性能的简化说法，请以当前标准讲解的条件和边界为准。')
def q(key,title,intro,code,prompt,choices,correct,feedback,body,boundary):
    ident=current['slug']+'/'+key
    t=dict(id=ident,knowledgeIds=[ident],title=title,intro=intro,code=code,prompt=prompt,
           fields=[dict(id='answer',label='你的判断',correctOptionId=f'o{correct}',options=[dict(id=f'o{i}',text=x,feedback=feedback[i]) for i,x in enumerate(choices)])],
           insight=body,ability=title,reading=reading(ident,title,body,boundary))
    current['tasks'].append(t);GUIDES['lessons'][current['slug']]['sections'].append(dict(id=ident,title=title,body=body,boundary=boundary));return t
def follow(t,key,title,code,prompt,choices,correct,feedback,newcode,newprompt,newchoices,newcorrect,why):
    t['remediation']=dict(id=current['slug']+'/'+key,knowledgeId=t['knowledgeIds'][0],title=title,intro='用另一份材料判断同一个问题。',code=code,prompt=prompt,
        field=dict(id='answer',label='变式判断',correctOptionId=f'r{correct}',options=[dict(id=f'r{i}',text=x,feedback=feedback[i]) for i,x in enumerate(choices)]),insight=why)
    DELAYED['items'].append(dict(id=current['slug']+'/'+key+'-delayed-v1',slug=current['slug'],taskId=t['id'],knowledgeId=t['knowledgeIds'][0],title=title,code=newcode,prompt=newprompt,
        options=[dict(id=f'd{i}',text=x) for i,x in enumerate(newchoices)],correctOptionId=f'd{newcorrect}',explanation=why))
RDD='rdd-programming-guide.html'
TUNE='sql-performance-tuning.html'

lesson('l1-what-is-rdd','把一批数字交给分布式计算','先预测数据和分区，再理解不可变与恢复。','RDD 不是 Driver 上完整结果列表，也不自动全部驻留内存。血缘恢复依赖上游可用且可重算，不是免费备份或任意外部副作用重放保证。',RDD)
q('parts','四份数据，不是四台机器','local[2] 中创建六个整数、四个分区。','sc = spark.sparkContext\nrdd = sc.parallelize([1,2,3,4,5,6], 4)','从这里能确定什么？',['计算划成四份，并发仍受资源限制','必须有四台机器','每分区必须正好一行'],0,['对，份数与机器或槽位不同。','分区不是机器编号。','分配不承诺每份恰一条。'],'RDD 用分区表示可分布式处理的元素集合；分区数和可用并行资源分开理解。','本课的小样本由本地列表创建，不表示大规模数据必须先收集到 Driver。')
t=q('immutable','加一后，原来的数字变了吗','原 rdd 为 2、4、6。','new = rdd.map(lambda x: x + 1)','两个查询各自请求结果时，应怎样理解？',['rdd 与 new 都自动变为 3、5、7','rdd 仍表示 2、4、6；new 表示 3、5、7','rdd 被删除'],1,['map 返回新 RDD，不就地修改旧定义。','对，两个 RDD 代表不同计算。','创建新查询不删除原变量。'],'RDD 转换返回新查询对象，Python 变量重新绑定也不等于就地修改原数据。','元素内部可变对象与外部副作用不能被这个比喻当成安全修改接口。')
follow(t,'immutable-transfer','旧查询仍然存在','a=sc.parallelize([3,7]); b=a.map(lambda x:x*2)','a.collect() 的结果应？',['[6,14]','[3,7]','空列表'],1,['这是 b 的结果。','对，原查询未被改写。','转换没有删除原数据。'],'x=sc.parallelize([5,8]); y=x.filter(lambda n:n>5)','x 的原始逻辑内容是？',['只有 8','5、8','空'],1,'转换生成新 RDD，不把原查询就地改成结果。')
q('recover','丢掉一份缓存靠什么恢复','上游文件仍可读取，转换可重算。','# 教学情境：某缓存分区丢失。','Spark 可以依靠什么重建？',['血缘中记录的上游与计算规则','自动永久备份了所有结果','只按分区编号猜数据'],0,['对，恢复仍有读取与计算代价。','RDD 不默认永久备份一切。','编号不包含业务值。'],'血缘描述依赖与计算关系，可在条件满足时重算丢失分区。','源数据不可再读、非确定逻辑或外部副作用会使恢复边界更复杂。')
q('storage','创建 RDD 就全部缓存了吗','只是建立 RDD，未显式缓存。','rdd = sc.parallelize([10,20,30],2)','哪个说法可靠？',['所有结果永久在内存','需要缓存/持久化策略时另行选择，创建不等于全量缓存','没有内存就不能创建描述'],1,['默认不提供这样的永久保证。','对，数据抽象和存储策略不同。','描述与全部结果驻留不同。'],'RDD 抽象、执行与缓存策略分开理解；持久化也受容量和存储级别影响。','不要将“内存计算”理解为完全没有磁盘或重算。')

lesson('l1-transformation','先写加工规则，再预测结果','在 map、filter 与 flatMap 中选对数据形状。','RDD 转换描述新计算，不等于 Catalyst 能理解任意 Python 函数体；记录增减不决定窄/宽依赖。',RDD)
q('map','每个数字变一个数字','输入 1、3、5。','rdd.map(lambda x:x*x)','请求结果后是哪组？',['1、9、25','1、3、5','只有 25'],0,['对，每元素独立平方。','没有应用平方规则。','map 不只保留最后一个。'],'map 为每个输入元素产生一个输出元素，结果内容由函数决定。','它本身不保证全局排序或跨分区汇总。')
t=q('flatmap','一行有两个词，会得到几层','输入两行："red blue"、"red"。','rdd.map(lambda line: line.split())\nrdd.flatMap(lambda line: line.split())','两种输出形状有什么差别？',['都只有一个字符串','map 得到词列表元素；flatMap 展平成词元素','flatMap 自动统计词频'],1,['函数返回值决定形状。','对，展开与聚合是不同操作。','还需要按词计数。'],'flatMap 允许每个输入产生零到多个输出，并将这层结果展开。','本课按空白分词，不自动处理标点、词形或业务字典。')
follow(t,'flatmap-transfer','拆分不等于计数','输入 "a b"、"b c"，flatMap(split)。','会得到什么？',['四个词元素，还没统计重复','三个去重词','一个计数 4'],0,['对，b 出现两次仍是两条。','flatMap 不自动去重。','计数需要另行 action 或聚合。'],'输入 "x y"、空行，用 flatMap(lambda s:s.split())。','输出几个词？',['3','2','0'],1,'flatMap 展开函数输出，不自动去重或聚合。')
q('filter','保留条件，不改数值','输入 -2、0、4、7。','rdd.filter(lambda x:x>0)','结果应是？',['4、7','0、4、7','2、0、4、7'],0,['对，只保留严格正数。','零不满足 >0。','filter 不把负数变正。'],'filter 保留谓词成立的元素，不能与数值变换混淆。','输出变少也不意味着分区数按同样比例减少。')
q('chain','步骤多就等于多次完整作业吗','只定义 map 与 filter，尚未请求结果。','b=rdd.map(lambda x:x+1).filter(lambda x:x>3)','应怎样理解？',['先定义计算链，实际执行与调度不按源码步骤固定计数','每个转换必独立跑一次完整 job','原始数据被永久改写'],0,['对，别把转换调用数当 job 数。','运行划分要看实际依赖与执行。','转换不是就地修改。'],'转换链可推迟实际求值，并按依赖执行；不要把它等同于 SQL 优化器任意理解 Python 逻辑。','某些操作可能需要辅助工作，不能把整个程序简化成 action 前绝对零开销。')

lesson('l1-action','什么时候真的请求结果','选 count、take 或 collect，分清结果规模和副作用。','action 不只把数据交给 Driver，也可能保存或执行分区逻辑；一次 action 不保证严格一个 job，外部写入也不自动 exactly-once。',RDD)
q('count','只想知道有几条','输入六个元素，只需要数量。','rdd.__A__()','A 最直接选什么？',['collect 后在 Driver 全部存下','count','map'],1,['为了数量收集全部元素没有必要。','对，返回数量而非全表元素。','map 返回新 RDD，不直接返回条数。'],'count 返回计数，collect 将全部结果收集到 Driver；选接口先看所需结果规模。','count 仍可能需要执行上游工作，不等于免费元数据查询。')
t=q('collect','十亿条结果能直接搬到 Driver 吗','Driver 容量有限，只想先看几条。','all_rows=rdd.collect()','更稳妥的做法是？',['直接收全表，Spark 保证 Driver 装得下','用有界样本/少量结果检查，完整交付另定方式','只把变量名改短'],1,['collect 不提供无限内存。','对，明确结果规模。','变量名不改变数据量。'],'collect 适用于已知很小的教学结果或有界产物，不应无条件搬运海量明细。','take 限制返回量，但上游成本仍由查询决定，也不代表均匀随机抽样。')
follow(t,'collect-transfer','只看三条，不必收全部','上游有百万记录，只需要有限预览。','哪种目标更合适？',['collect 全部再切片','请求有限条结果并评估上游代价','所有记录必须存在 Driver'],1,['切片前已收集全部。','对，返回规模应有界。','分布式数据不要求这样收集。'],'只需记录数，不需要记录内容。','更直接的 action 是？',['collect 全部','count','map'],1,'按目标限制 Driver 接收规模；计数不需要收集全部记录内容。')
q('foreach','闭包里追加，Driver 列表会跟着变吗','在分布式任务里运行函数。','seen=[]\nrdd.foreach(lambda x: seen.append(x))','能把它当 Driver 收集接口吗？',['能，闭包天然共享同一个列表','不能，任务中的闭包与 Driver 状态不能这样当共享结果','会自动按序返回 seen'],1,['分布式任务不提供该共享列表语义。','对，需采用适合的结果/聚合接口。','foreach 不返回这样的有序集合。'],'任务闭包的副作用不等于可靠的 Driver 汇总；外部副作用还可能受重试影响。','不要把本地偶然表现外推为集群共享状态或 exactly-once 保证。')
q('again','count 之后已经自动缓存了吗','先 count，再 take，未显式选择持久化。','rdd.count()\nrdd.take(2)','能保证第二次完全不算上游吗？',['能，任何 action 都自动缓存','不能，复用/重算与持久化和执行条件有关','第二个 action 必报错'],1,['action 不是自动全量缓存承诺。','对，是否复用要看实际策略。','多个 action 可以合法调用。'],'请求结果和保存可复用状态是两回事，多次 action 可能重复部分工作。','持久化也可能因逐出、失败或未物化而不能避免全部重算。')

lesson('l1-lazy-evaluation','还没取结果，先把路线写清','看哪些分支会用到，再理解缓存与可重算。','RDD 的惰性执行不意味着没有任何 Driver 工作，也不等于拥有所有 SQL 级语义优化；缓存标记与实际缓存内容不同。',RDD)
q('predict','定义平方后还没请求它','输入 2、3，建立平方查询后只打印变量类型。','squared=rdd.map(lambda x:x*x)\nprint(type(squared))','这是否等于已得到全部平方结果？',['不是，只知道创建了查询对象','是，全部已 collect','是，永久落盘了'],0,['对，类型不是完整业务结果。','没有 collect。','没有保存操作。'],'惰性变换描述依赖与计算，结果请求才驱动所需计算路径。','创建对象和分析输入等工作仍可能发生在 Driver，不能说整个程序零成本。')
t=q('branches','没用到的支路也必须跑吗','同一输入建了两条不同转换，只请求其中一条。','a=rdd.map(lambda x:x+1)\nb=rdd.map(lambda x:x*10)\na.count()','应怎样理解执行需求？',['必须把 a 和 b 全部求值','按当前 action 所需依赖执行，不因定义了 b 就必算它','只执行 b'],1,['未请求的无关分支不是这个 action 的需求。','对，顺着实际依赖理解。','当前请求的是 a。'],'执行从 action 的依赖出发，不是按变量定义顺序把所有潜在结果都做完。','实际缓存、共享上游与调度行为应结合执行记录。')
follow(t,'branch-transfer','定义不等于必跑','创建正数分支 p 与负数分支 n，只请求 p 的结果。','能断言 n 也必完整运行吗？',['不能，要看所需依赖','能，变量存在即求值','只能运行 n'],0,['对，不相关分支不是当前请求。','定义不是结果请求。','当前目标是 p。'],'定义两个不同下游，只 collect 其中一个。','怎样推断工作范围？',['把所有变量都当结果请求','沿 action 的依赖检查','只按源码行号'],1,'惰性执行应按结果请求的依赖理解，而不是按所有变量逐个求值。')
q('persist','cache 写下了，数据就全部热了吗','只调用 cache，尚未做遍历全部数据的请求。','cached=rdd.cache()','哪个判断正确？',['只标记持久化意图，不保证全量已物化','所有分区已经永久在内存','cache 自动返回 Python 列表'],0,['对，实际填充取决于执行需求。','标记不是完成保证。','返回值仍是 RDD。'],'持久化标记与实际物化分区不同，需要结合 action 和存储情况核对。','缓存可能被逐出，存储级别和容量会影响复用。')
q('recovery','重算不等于副作用只一次','任务执行中向外部系统写数据，随后发生重试。','# 教学情境：外部写入不是 Spark 原子提交的一部分。','能自动保证只写一次吗？',['能，血缘就是事务日志','不能，需幂等或适合的提交机制','重试会自动删除外部旧数据'],1,['血缘不是任意外部系统事务。','对，副作用语义要单独设计。','不能依赖这样的自动删除。'],'容错重算与外部副作用一致性是不同问题，不能把恢复机制当作 exactly-once。','本章练习不执行外部写入。')

lesson('l1-why-dataframe-replaces-rdd','结构化问题，先选能表达语义的工具','比较同一任务的表达能力，而不是给接口排永久胜负。','DataFrame 依赖字段和表达式结构供优化；RDD 仍有适用场景，不代表永远过时或任何 DataFrame 写法都更快。','sql-getting-started.html')
q('schema','金额是哪一列，类型是什么','业务是按地区汇总金额，字段和类型已明确。','# 结构化输入：region string，amount long。','先考虑哪类表达？',['DataFrame/SQL 的筛选与聚合表达式','把整表转成 Python 字符串再拼接','只按变量名字判断金额'],0,['对，接口可直接表达字段与关系。','会丢掉结构且增加不必要处理。','名字不能代替 Schema。'],'结构化数据适合使用 DataFrame/SQL 表达列、类型和关系，优化器可据此分析查询。','输入质量、NULL 和业务规则仍需显式验证。')
t=q('optimizer','Python 函数体会被当 SQL 代数随意重写吗','RDD map 中封装任意 Python 逻辑。','rdd.map(custom_python_function)','可靠认识是？',['Catalyst 一定理解函数体的所有语义','不能这样保证；结构化表达与任意函数体不同','RDD 自动变成永久 SQL 表'],1,['不能给任意函数这样的保证。','对，接口暴露的信息不同。','这不是 map 的结果。'],'结构化表达向优化器暴露的语义比任意 Python 函数体更明确。','这不提供任何接口在所有输入上固定更快的承诺。')
follow(t,'optimizer-transfer','同需求的两种表达','一种用内置列表达式，一种藏进任意 Python UDF。','能假定优化器看到完全相同的信息吗？',['能，函数名相同即可','不能，需核对执行与优化边界','必须都 collect'],1,['函数名不证明内部语义可分析。','对，执行路径与边界不同。','不是必须收全表。'],'结构化聚合可以用列/键表达，也可手写对象处理。','选择时首先考虑？',['需求、结构和可验证执行','固定 RDD 永远更快','固定 SQL 永远更快'],0,'表达能力与暴露的语义影响可优化性，性能仍需具体测量。')
q('still-rdd','RDD 什么时候仍有意义','需求是自定义分区级处理，现有结构化表达不合适。','# 教学情境：明确需要低层控制。','应如何选择？',['任何情况都禁止 RDD','评估 RDD 与转换边界，保留正确性与资源验证','所有 API 随便混用不用验证'],1,['低层抽象仍可有适用场景。','对，工具选择由需求决定。','转换和执行可能有额外成本。'],'DataFrame 是结构化任务常用入口，RDD 仍服务特定低层处理；避免绝对接口排名。','选低层控制也意味着更多类型、资源和语义责任。')
q('bridge','转换时类型不能靠猜','准备将整数与文本记录转为 DataFrame。','spark.createDataFrame(rows, schema)','还需明确什么？',['字段、类型、NULL 与业务约定','只需要短变量名','不需要验证输入'],0,['对，把隐含假设变成可检查结构。','名称不定义类型或质量。','转换成功不等于业务正确。'],'从对象集合转结构化数据时明确 Schema，并验证真实输入和业务规则。','类型推断不是无限可靠的业务校验，文件读取还受解析策略影响。')

lesson('l1-rdd-exercise','准备练习：把文本变成可核对的词频','六步是可选热身，独立任务会换文本、空行与分区数。','分词规则必须明确；RDD collect 只用于已知小教学结果，分区调节不应改变计数，血缘也不提供外部写入认证。',RDD)
q('contract','先说什么算一个词','输入中有大小写、多个空格和标点。','# 本任务：空白切词，小写；标点保留。','最先需要做什么？',['明确分词/归一与计数约定','直接剥掉所有字符','把每行当唯一词'],0,['对，预期结果取决于规则。','会破坏原始信息。','与本任务分词规则不同。'],'独立实作先定义词与相等规则，再选择变换和聚合。','本任务不是完整自然语言处理或语言分词系统。')
