q('aqe','设置值与最终任务数','设置shuffle分区200且开启AQE。','# 核对执行后计划。','应保留哪个认识？',['所有阶段永远200task','最终可能调整，需要实际核对','代表200行结果'],1,['配置不代表所有阶段。','对，观察最终执行。','参数不是业务行数。'],'把初始配置、算子分布与最终AQE划分分开记录。','不同版本和查询适用性会改变实际行为。')
q('capacity','大份与并发一起看','每个task状态很大，同时运行多个task。','# 合成指标：内存峰值与spill上升。','实验前还需核对？',['最大分区、算子状态和并发容量','只看整表平均大小','先宣称参数越大越快'],0,['对，任务与节点容量共同约束。','平均可能掩盖风险。','没有这种保证。'],'调整粒度既可能降低单份状态，也可能改变并发与管理开销，需同条件测量。','结果必须保持等价。')

lesson('l7-broadcast-threshold','不是把阈值抬高就叫优化','对照统计、构建容量、实际采用与收益。','自动阈值、显式提示与AQE控制分开；压缩文件不等于哈希内存，关闭自动广播也不指定唯一回退策略。',TUNE)
q('stats','估计大，文件小，先查统计','计划估计与新文件规模明显不同。','# 合成观察：尚未核对统计时效。','先做什么？',['核对数据来源、统计和实际构建规模','直接把所有阈值设无限','只看文件名'],0,['对，先修正选择依据。','可能引入内存风险。','名称不是规模证据。'],'策略判断受可用统计影响，先核对估计与实际工作集再试参数。','不是所有临时来源都可用同样的ANALYZE命令补统计。')
t=q('memory','小压缩文件也可能占大内存','维表压缩体积小，但构建结构和并发未知。','# 同时有多条查询。','可直接保证广播安全吗？',['可以，文件体积就是内存','不行，需看展开、构建、并发和节点余量','只看总磁盘空间'],1,['不是同一口径。','对，核对真实容量。','磁盘总量不替代内存预算。'],'广播容量与实际构建关系、并发和节点内存有关，而不是单看压缩文件。','计划统计也不是运行内存上限。')
follow(t,'broadcast-transfer','采用与安全分开','# 计划已出现BroadcastHashJoin。','还需验证什么？',['容量、结果与代表性指标','固定宣称快十倍','删除所有正确性断言'],0,['对，采用不等于安全或收益。','没有固定倍数。','正确性不能省。'],'# 关闭自动阈值但代码仍有显式broadcast。','能保证所有广播关闭吗？',['能','不能，控制层次需分开','自动变CROSS'],1,'阈值、提示、容量与实际收益分别核对，不能混为一个开关。')
q('support','没有等值键仍要看算法支持','连接是范围条件，给了广播提示。','# 提示不改变业务条件。','能无条件认定采用BHJ吗？',['能','不能，广播可能走其他适用路线','必须改成等号才能算正确'],1,['哈希算法有适用条件。','对，看实际物理节点。','不能为选型改变业务语义。'],'广播建议与具体连接算法不同，连接条件和类型仍约束实现。','先保证正确保留规则和匹配基数。')
q('rollback','阈值变大后更慢','计划改了，构建等待和内存压力也上升。','# 合成对比：结果相同，资源变差。','合理做法？',['保留因为参数更大','回退并复查容量与替代路线','只报告节点变了'],1,['参数变大不是目标。','对，保留可审查回退。','计划变化不等于成功。'],'优化以正确结果和目标指标评价，实施、容量与收益分开验收。','同条件重复试验减少偶然波动影响。')

lesson('l7-aqe','看到最终路线，再解释自适应','确认配置、输入统计与执行后的变化，不背万能开关。','AQE有版本与适用条件；子开关为true不等于总开关或全部优化生效。初始计划未final不能当最终证据。',TUNE)
q('check','先确认实际配置','同事说“新版本默认开了”，但应用可覆盖设置。','spark.conf.get("spark.sql.adaptive.enabled")','该怎样做？',['核对当前会话配置与实际效果','只背一个默认值','认为所有子功能都必应用'],0,['对，默认与当前值不同。','默认不能代替应用状态。','有适用条件。'],'先查实际配置与版本，再看执行后是否有相关调整。','本课以3.5.7文档为语义参考，实跑版本另记。')
t=q('final','false不表示失败','计划显示 AdaptiveSparkPlan isFinalPlan=false。','# 查询尚未按代表输入完成执行。','下一步？',['把初始图当最终事实','执行所需结果后结合最终计划与指标','认定优化器已坏'],1,['状态已经提示不是最终。','对，记录前后变化。','不是这样的错误声明。'],'AQE初始计划可能与执行后不同，应核对同一目标查询的最终证据。','action本身也可能改变实际执行的查询，注意比较对象。')
follow(t,'aqe-transfer','开启不等于生效','# 总开关为true，但某查询不满足特定转换条件。','该认定什么？',['所有转换必发生','需核对适用性和最终计划','必须认为数据为空'],1,['开关不是转换保证。','对，确认实际变化。','不是业务结果声明。'],'# 某子开关为true，总开关与版本未检查。','能认定功能实际生效吗？',['能','不能，需完整核对','必定关闭全部SQL'],1,'配置、适用条件与实际采用是不同证据。')
q('coalesce','很多小分区被合并','执行后的Shuffle任务数减少，结果一致。','# 合成观察：需核对是否为AQE合并。','合理解释是？',['必定丢掉数据','可能为自适应合并，结合最终计划确认','所有查询固定减少一半'],1,['任务数不等于业务行数。','对，变化还需证据定位。','没有固定比例。'],'合并小分区可降低某些管理成本，但要核对实际调整与工作负载。','结果、资源和耗时分别验收。')
q('limits','AQE会修复错误JOIN吗','维表重复导致金额翻倍，已开AQE。','# 语义错误与执行优化分开。','应怎样处理？',['等待AQE自动改业务规则','先修维表约定或连接规则','只提高参数'],1,['物理自适应不替代正确语义。','对，先保证结果。','参数不能定义唯一性。'],'自适应优化应保持原查询语义，不能替代业务质量与基数验证。','有错语义即使更快，也不是成功。')

lesson('l7-skew-tuning','长尾的治疗也要保留业务事实','从热点、异常与匹配规模定位，再正确拆分和还原。','长尾是线索不是唯一病因；删除NULL须业务允许，salting需配套匹配/还原，不能只对比总行数就认证语义。',TUNE)
q('diagnose','最大值很高先定性吗','大多数task两秒，一个九十秒。','# 合成症状，尚未看字节/键/GC/机器。','先做什么？',['核对负载与运行证据，不只凭耗时定病因','立刻删除最慢键','只看平均即验收'],0,['对，长尾有多种原因。','可能丢业务事实。','平均会掩盖问题。'],'将长尾与键、字节、spill、匹配基数和其他异常一起核对。','合成症状不是生产基准或唯一诊断。')
t=q('weighted','拆开后能直接平均均值吗','一份count=1、avg=100；另一份count=9、avg=0。','# 合并同一组的平均值。','全局平均应是？',['50','10','100'],1,['直接平均各份均值忽略权重。','对，sum=100、count=10。','漏掉另一份九个值。'],'拆分聚合必须保留可正确合并的状态，AVG可用sum/count还原，不能一般地平均局部均值。','NULL与分母约定也要保持一致。')
follow(t,'weighted-transfer','先保留可合并状态','# A: sum=40,count=2；B: sum=60,count=6。','合并平均值是？',['15','12.5','20'],1,['这是把20和10直接平均。','对，100/8。','漏了B的贡献。'],'# 两组局部均值相同，但样本数不同。','一般方法还应保留什么？',['sum与非空count','只保留一个均值','只保留分区号'],0,'可合并状态必须足以还原业务指标，均值合并需要正确分母。')
q('salt','单边加盐会有什么风险','事实改键，维表没有相应扩展。','# 为拆热键准备改写。','应先保证什么？',['匹配与还原规则不漏不重','只要更快就可随意改键','只比较最终总行数就够'],0,['对，保留原逻辑关系。','速度不能代替正确性。','相同行数也可能错误配对。'],'salting需要一致的匹配策略与结果还原，并验证逐组指标与业务粒度。','它有膨胀和复杂度成本，不是所有长尾的首选。')
q('null','未知键是否能直接删','热点来自NULL，但业务要求保留未知用户贡献。','# 合法事实中有缺失键。','可为加速直接过滤吗？',['可以，NULL永远无用','不可以，先遵守业务缺失口径','只改成INNER即可'],1,['缺失不等于无业务价值。','对，不能靠丢事实优化。','可能同样丢掉事实。'],'异常/缺失键处理必须与业务约定一致，优化不得悄悄改变指标分母。','若业务允许排除，也应记录规则与数量。')

lesson('l7-read-less-data','少做无用功，也要守住语义','从字段、行、交换、重复计算中选择一项有证据的改动。','缓存列式数据仍可只扫描所需列；下推/目录裁剪取决于源与条件，先聚合再JOIN也必须证明粒度等价。',TUNE)
q('columns','缓存之后，选列就完全没意义了吗','使用Spark SQL列式缓存，下游只用三列。','# 参考官方列式缓存机制。','可靠认识是？',['缓存后一律全列读取','仍应核对所需列扫描与执行收益','缓存会自动保证永不重算'],1,['不能这么绝对概括。','对，缓存也不取消字段需求。','缓存仍有容量与逐出等条件。'],'Spark SQL列式缓存可按所需列扫描；减少无用字段与缓存复用是不同层次。','具体收益要看源、缓存和算子路径。')
t=q('pushdown','下推有痕迹还要读残余条件','扫描只下推一部分条件，物理计划仍有Filter。','# 教学片段：PushedFilters + residual Filter。','应怎样处理？',['认定所有业务过滤都在源端完成','核对已下推与残余语义','删掉所有Filter'],1,['标记不证明所有条件。','对，二者可能共同完成过滤。','可能删掉必要规则。'],'数据源能力与具体表达式决定下推，残余过滤仍可能必需。','下推存在不直接证明实际读字节下降多少。')
follow(t,'read-transfer','少读的证据要具体','# 仅有ReadSchema缩小，没有代表性IO测量。','结论应是什么？',['结构线索已观察，收益待测','生产一定快十倍','所有缓存都无效'],0,['对，证据与结论范围匹配。','没有这样的测量。','没有这种推论。'],'# 某条件无法被当前数据源下推。','是否可以为了少读直接删条件？',['可以','不可以，业务语义仍要执行','只要更快就行'],1,'减少工作应通过合法优化并验证收益，不能通过删业务条件实现。')
q('preaggregate','先聚合再连接总等价吗','维表重复键可能放大结果，准备把聚合移到连接前。','# 关注连接粒度、过滤与匹配基数。','首先需要什么？',['证明改写语义与指标等价','只看数据量更小','无条件认为更快更正确'],0,['对，移动聚合可能改变粒度。','更少数据不能证明等价。','要看需求和关系。'],'提前聚合可减少某些工作，但只有在粒度、过滤和匹配规则允许时才能保持结果。','外连接、重复键和非可加指标尤其要验证。')
q('reuse','一次性小计算也要缓存吗','只用一次，原计算很便宜，缓存成本不明。','# 目标是整体资源和耗时。','更合理的做法？',['所有中间结果都缓存','先比较复用次数、预热、容量和重算成本','缓存保证无内存开销'],1,['会制造不必要开销。','对，按实际复用需求选择。','缓存占资源也有管理成本。'],'缓存是有代价的复用策略，不能把cache当作所有慢作业的默认第一步。','没有复用或便宜重算时，收益可能不足。')

lesson('l7-comprehensive','准备练习：让每项建议都能被复核','独立任务要求正确结果、实际计划与有回退的诊断，不是填写参数清单。','本地小样本、合成症状和计划变化不等于生产收益；诊断文字质量仍需人工核对。',TUNE)
q('contract','先锁定要守住的结果','准备比较原实现与改写。','# 输出粒度、正金额规则、NULL地区口径已约定。','第一条验收是什么？',['逐组结果与类型保持约定','代码更短','参数更大'],0,['对，正确性先于性能。','短代码也可能错。','参数不是目标。'],'调优实验先定义业务不变量，再解释哪些工作可能被消除。','总计正确也可能掩盖逐组错分。')
q('symptom','看见Python边界，假设还需实测','简单地区清洗使用普通Python UDF，内置表达式可能等价。','# 教学情境：未做生产测量。','更合适的提案是？',['保持语义替换为内置，核对计划与代表性指标','保证省十倍时间','直接删清洗步骤'],0,['对，单一可回退的实验。','没有固定倍数证据。','会改变结果。'],'将可表达的逻辑换成内置是可检验假设，采用与收益需要分别验证。','不要在小样本计时上作生产保证。')
t=q('compare','一次改六个参数，收益从哪来','结果相同但同时改了多项设置，只有一次耗时。','# 合成试验记录不充分。','应如何改进实验？',['只保留最漂亮数字','控制条件、尽量单一改动并保留前后证据','宣称所有改动都有效'],1,['选择性报告不可复核。','对，减少混杂因素。','无法分辨各项贡献。'],'诊断与调优需要可重复实验，明确数据、配置、缓存和资源条件。','必要组合改动也应说明交互与验证计划。')
follow(t,'experiment-transfer','对照条件要可比','# 原方案冷缓存，新方案热缓存，输入量也不同。','能直接报告代码加速倍数吗？',['能','不能，条件混杂','只看代码行数'],1,['无法可靠归因。','对，先控制或记录变量。','行数不证明性能。'],'# 同条件结果一致，单次运行快了少许。','还应做什么？',['重复测量并看资源/波动','固定宣布生产成功','删除回退方案'],0,'结果正确与条件可比是归因基础，重复与资源指标帮助解释变化。')
q('rollback','没有收益，也要算有效实验','改写结果正确但代表性运行指标变差。','# 有清晰基线。','该怎么交付？',['回退或拒绝改动，保留证据与新假设','隐去失败数字','只因节点少就保留'],0,['对，负结果同样有信息。','会破坏可审查性。','节点少不保证总成本更低。'],'实验可以否定假设，回退和清楚记录比参数堆叠更可靠。','不要通过改变业务口径伪造收益。')
q('scope','哪种PASS真的经过验证','自动脚本检查了查询结果与计划，诊断自由文本仅保存。','# manual_review=required。','正确报告是什么？',['自动检查过，文字论证仍待人工复核','所有能力与生产性能都已认证','文字非空就自动证明推理正确'],0,['对，清楚划分验收边界。','超出了自动证据。','非空只证明提交了草稿。'],'自动化检查覆盖明确的结果与结构；自由诊断的合理性不能被非空检查冒充评分。','学习效果仍需真实使用与独立情境验证。')
q('next','换数据也要成立','验收会换地区、空输入、空值与无效金额。','# 正确性与边界检查。','可靠实现应？',['按传入数据与契约计算','写死原样例总额','只在看过答案的输入运行'],0,['对，新材料检验规则。','无法适应变化。','熟悉答案不是新的独立证据。'],'最终交付同时给出可运行实现、明确限制与下一步验证计划。','本地验证不覆盖所有版本或大规模资源场景。')

for index,t in enumerate(t for l in lessons.values() for t in l['tasks']):
    if not t['id'].startswith(('l1-','l7-')):continue
    f=t['fields'][0];correct=next(o for o in f['options'] if o['id']==f['correctOptionId']);others=[o for o in f['options'] if o['id']!=f['correctOptionId']]
    others.insert(index%3,correct);f['options']=others
GUIDES['version']=max(GUIDES['version'],4);DELAYED['version']=max(DELAYED['version'],4)
DELAYED['items'].sort(key=lambda x:(x['slug'],x['id']))
from concept_progression import apply as apply_concept_bridges
apply_concept_bridges(lessons, GUIDES, DELAYED)
outputs={ROOT/'lessons'/f'{slug}.json':l for slug,l in lessons.items()};outputs[ROOT/'standardGuides.json']=GUIDES;outputs[ROOT/'delayedChecks.json']=DELAYED
for path,data in outputs.items():
    text=json.dumps(data,ensure_ascii=False,indent=2)+'\n'
    if '--check' in sys.argv:assert path.read_text(encoding='utf-8')==text,str(path)
    else:path.write_text(text,encoding='utf-8')
print('PASS L1/L7',len(lessons),'lessons /',sum(len(l['tasks']) for l in lessons.values()),'steps, preserving tuning pilot IDs')
